  const fetchAmbassadors = async () => {
    try {
      const res = await apiFetch(`${API}/auth/users/?role=ambassador`, {}, onLogout)
      if (res && res.ok) {
        const data = await res.json()
        setAmbassadorsList(Array.isArray(data) ? data : [])
      }
    } catch {}
  }

  const handleAssignAmbassador = async (orphanageId, ambassadorId) => {
    setOrphanageLoading(true)
    try {
      const res = await apiFetch(`${API}/orphanages/${orphanageId}/assign-ambassador/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ambassador_id: ambassadorId }),
      }, onLogout)
      if (!res) return
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || "Erreur d'assignation")
      showToast("Ambassadeur assigné avec succès.", 'success')
      setAssigningId(null)
      loadOrphanages()
    } catch (err) {
      showToast(err.message, 'error')
    } finally {
      setOrphanageLoading(false)
    }
  }

  const orpFileHandler = (key) => (e) => { const file = e.target.files?.[0]; if (file) setOrpFiles(p => ({ ...p, [key]: file })); }
  const orpDragHandler = (key) => ({ onDragOver: e => e.preventDefault(), onDrop: e => { e.preventDefault(); const file = e.dataTransfer.files?.[0]; if (file) setOrpFiles(p => ({ ...p, [key]: file })); } })
  const directorOrpRec = () => orphanageRequests.find(o => String(o.director) === String(user.id))

  useEffect(() => {
    if ((activeKey === 'orphelinats' || activeKey === 'validationLocale') && role === 'federation') {
      loadOrphanages()
      fetchAmbassadors()
    }
    if (activeKey === 'ambassadeurs' && (role === 'federation' || role === 'supermaster')) {
      loadOrphanages()
      fetchAmbassadors()
    }
  }, [activeKey, role])

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme)
    localStorage.setItem('cdo_theme', theme)
  }, [theme])

  useEffect(() => {
    if (bgTheme) {
      document.documentElement.setAttribute('data-bg', bgTheme)
    } else {
      document.documentElement.removeAttribute('data-bg')
    }
    localStorage.setItem('cdo_bg', bgTheme)
  }, [bgTheme])

  useEffect(() => {
    if (bgCombo) {
      const left = BACKGROUND_LIBRARY.find(bg => bg.id === bgCombo.leftId)
      const right = BACKGROUND_LIBRARY.find(bg => bg.id === bgCombo.rightId)
      if (left && right) {
        document.documentElement.style.setProperty('--bg-overlay',
          `url('${bgPhotoUrl(left)}') left/50% 100% no-repeat, url('${bgPhotoUrl(right)}') right/50% 100% no-repeat`)
        localStorage.setItem('cdo_bg_combo', JSON.stringify(bgCombo))
        return
      }
    }
    document.documentElement.style.removeProperty('--bg-overlay')
    localStorage.removeItem('cdo_bg_combo')
  }, [bgCombo])

  useEffect(() => {
    const fetchChildren = async () => {
      try {
        const res = await apiFetch(`${API}/enfants/`, {}, onLogout)
        if (res && res.ok) setRegisteredChildren(await res.json())
      } catch (err) {
        console.error('Failed to fetch children:', err)
      }
    }
    fetchChildren()
  }, [activeKey])

  // Synchronisation photo locale -> backend : les photos choisies via
  // « Enfants enregistrés » / « Mise à jour » n'existaient que dans le
  // localStorage de CE navigateur. Dès que la liste est chargée, toute photo
  // locale absente du serveur est envoyée (Base64ImageField accepte les
  // data-URLs), pour qu'elle apparaisse partout : Projets, Accueil, landing.
  const photoSyncAttempted = useRef(new Set())
  useEffect(() => {
    if (!registeredChildren.length) return
    registeredChildren.forEach(child => {
      if (child.photo || !child.uid || photoSyncAttempted.current.has(child.uid)) return
      const local = localStorage.getItem('cdo_child_photo_' + child.uid)
      if (!local || !local.startsWith('data:image')) return
      photoSyncAttempted.current.add(child.uid)
      // PUT partiel (le endpoint n'accepte pas PATCH mais fait partial=True)
      apiFetch(`${API}/enfants/${child.id}/`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ photo: local }),
      }, onLogout)
        .then(r => {
          if (r && r.ok) {
            setRegisteredChildren(prev => prev.map(c => c.id === child.id ? { ...c, photo: local } : c))
          }
        })
        .catch(() => {})
    })
  }, [registeredChildren, onLogout])

  useEffect(() => {
    const t = setTimeout(async () => {
      const url = childSearchQuery.trim()
        ? `${API}/enfants/?search=${encodeURIComponent(childSearchQuery.trim())}`
        : `${API}/enfants/`
      try {
        const res = await apiFetch(url, {}, onLogout)
        if (res && res.ok) setRegisteredChildren(await res.json())
      } catch {}
    }, 350)
    return () => clearTimeout(t)
  }, [childSearchQuery, onLogout])

  useEffect(() => {
    if (!hcHistoryChild?.id) { setHcEvents([]); return }
    let cancelled = false
    ;(async () => {
      let apiEvents = []
      try {
        const res = await apiFetch(`${API}/enfants/${hcHistoryChild.id}/history/`, {}, onLogout)
        if (!cancelled && res && res.ok) {
          const data = await res.json()
          apiEvents = Array.isArray(data) ? data : (data.results || data.events || [])
        }
      } catch (err) {
        console.error('Failed to fetch history:', err)
      }
      if (cancelled) return
      const stored = JSON.parse(localStorage.getItem('cdo_updates_' + hcHistoryChild.uid) || '[]')
      const localEvents = stored.map(s => ({
        id: s.id,
        event_type: s.event_type || 'update_added',
        category: s.category,
        update_type: s.update_type,
        subcategory: s.subcategory || '',
        title: s.title,
        description: s.description,
        old_value: s.previous_value || '',
        new_value: s.new_value || '',
        reason: s.reason || '',
        priority: s.priority || 'normal',
        source_module: s.source_module || 'update_center',
        attachments: s.attachments || [],
        performed_by_name: s.created_by || s.created_by_name || '',
        department: s.department || '',
        event_date: s.event_date || s.created_at,
        metadata: s.metadata || {},
      }))
      const merged = [...apiEvents.map(e => ({ ...e, event_type: e.event_type || 'update_added', performed_by_name: e.performed_by_name || '', department: e.department || '', priority: e.priority || 'normal', source_module: e.source_module || 'update_center', attachments: e.attachments || [] }))]
      for (const le of localEvents) {
        const exists = merged.find(m => m.id === le.id || (m.title === le.title && m.event_date === le.event_date && m.event_type === le.event_type))
        if (!exists) merged.push(le)
      }
      merged.sort((a, b) => new Date(b.event_date||0) - new Date(a.event_date||0))
      setHcEvents(merged)
    })()
    return () => { cancelled = true }
  }, [hcHistoryChild?.id])

  const deleteChild = async (child) => {
    try {
      const res = await apiFetch(`${API}/enfants/${child.id}/`, { method: 'DELETE' }, onLogout)
      if (res && res.ok) {
        setRegisteredChildren(prev => prev.filter(c => c.id !== child.id))
        setSelectedRegChild(null)
      }
    } catch (err) {
      console.error('Failed to delete child:', err)
    }
    setDeleteConfirm(null)
  }

